<script lang="ts">import { onMount } from 'svelte'; import { api } from '$lib/api'; type Item={asset:{name:string;assetTag?:string|null;branchId?:string|null};deploymentMode:string;haRole:string;policyOwner:string;updatedAt:string}; let items:Item[]=[];let loading=true;let error='';onMount(async()=>{try{items=(await api.get<{items:Item[]}>('/api/firewalls')).items;}catch(e){error=(e as Error).message}finally{loading=false}});</script>
<svelte:head><title>Firewalls — Oracle Inventory</title></svelte:head><div class="page"><h1>Firewalls</h1><p>Branch-scoped firewall metadata only. Rules and credentials are never displayed.</p>{#if loading}<section class="panel" role="status">Loading firewall profiles…</section>{:else if error}<section class="panel" role="alert">{error}<button onclick={() => location.reload()}>Retry</button></section>{:else if !items.length}<section class="panel">No firewall profiles are available in your authorized scope.</section>{:else}<section class="panel"><table><caption class="sr-only">Firewall profiles</caption><thead><tr><th>Asset</th><th>Mode</th><th>HA role / failover</th><th>Policy owner</th><th>Last updated</th></tr></thead><tbody>{#each items as item}<tr><td>{item.asset.name} · {item.asset.assetTag ?? 'No tag'}</td><td>{item.deploymentMode}</td><td>{item.haRole}</td><td>{item.policyOwner}</td><td>{item.updatedAt}</td></tr>{/each}</tbody></table></section>{/if}</div><style>.page{max-width:1100px;margin:auto;padding:32px}.panel{border:1px solid #ddd;border-radius:10px;padding:20px;margin-top:16px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:10px;border-bottom:1px solid #ddd}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}</style>
